INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist es wahr, dass ein wiederaufbereitetes Gerät immer wie neu funktioniert?', 2, '[{"text": "Nein", "correct": true, "because": "Kann leichte Abnutzung haben"}, {"text": "Ja", "correct": false, "because": "Nicht immer identisch mit neu"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Prozess ist entscheidend, um Daten von alten Geräten zu entfernen?', 3, '[{"text": "Datenlöschung", "correct": true, "because": "Sichert Datenschutz"}, {"text": "Formatierung", "correct": false, "because": "Nicht ausreichend sicher"}, {"text": "Komprimierung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte sind bei der Wiederaufbereitung eines Laptops wichtig?', 5, '[{"text": "Funktionstest", "correct": true, "because": "Sichert Betrieb"}, {"text": "Reinigung", "correct": true, "because": "Verbessert Zustand"}, {"text": "Farbanpassung", "correct": false, "because": "Nur kosmetisch"}, {"text": "Neuer Akku", "correct": false, "because": "Nur bei Bedarf"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Wiederaufbereitung verlängert die Lebensdauer. b) Sie ist immer teurer als Neukauf.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, oft günstiger"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Wiederaufbereitung eines Smartphones?', 4, '[{"text": "Software-Updates", "correct": false, "because": "Wichtig für Sicherheit"}, {"text": "Bildschirmprüfung", "correct": false, "because": "Entscheidend für Funktion"}, {"text": "Originalverpackung", "correct": true, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein wiederaufbereitetes Gerät immer eine Garantie hat?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig vom Anbieter"}, {"text": "Ja", "correct": false, "because": "Nicht immer garantiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Verfahren stellt sicher, dass ein Gerät voll funktionsfähig ist?', 4, '[{"text": "Stresstest", "correct": true, "because": "Prüft Belastbarkeit"}, {"text": "Oberflächenpolitur", "correct": false, "because": "Nur kosmetisch"}, {"text": "Neustart", "correct": false, "because": "Zu oberflächlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Wiederaufbereitung nur für Elektronik gilt. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Auch Möbel, Autos möglich"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein wiederaufbereitetes Gerät dasselbe wie ein gebrauchtes?', 2, '[{"text": "Nein", "correct": true, "because": "Gebraucht nicht geprüft"}, {"text": "Ja", "correct": false, "because": "Wiederaufbereitet ist getestet"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen eine Wiederaufbereitung nachhaltig?', 5, '[{"text": "Ressourcenschonung", "correct": true, "because": "Weniger Neuproduktion"}, {"text": "Abfallreduktion", "correct": true, "because": "Vermeidet Müll"}, {"text": "Schnelle Verarbeitung", "correct": false, "because": "Kein Kernfaktor"}, {"text": "Hohe Kosten", "correct": false, "because": "Nicht nachhaltig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Wiederaufbereitung eines Druckers?', 4, '[{"text": "Funktion der Druckköpfe", "correct": true, "because": "Kern der Leistung"}, {"text": "Gehäusefarbe", "correct": false, "because": "Nur kosmetisch"}, {"text": "Papierfachgröße", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Datenlöschung ist Pflicht. b) Alle Geräte werden recycelt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) nur bei Defekt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Wiederaufbereitung eines PCs?', 3, '[{"text": "Funktionstest", "correct": false, "because": "Prüft Leistung"}, {"text": "Datenlöschung", "correct": false, "because": "Sichert Datenschutz"}, {"text": "Designeraufkleber", "correct": true, "because": "Nur dekorativ"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, wie ich ein Gerät auf Funktionalität prüfe?', 4, '[{"text": "Diagnosesoftware nutzen", "correct": true, "because": "Genaue Ergebnisse"}, {"text": "Nur visuell prüfen", "correct": false, "because": "Zu oberflächlich"}, {"text": "Farbe kontrollieren", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass wiederaufbereitete Geräte keine Updates bekommen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Updates meist verfügbar"}, {"text": "Ja", "correct": false, "because": "Abhängig vom Gerät"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip hilft, die Qualität eines Geräts zu sichern?', 3, '[{"text": "Zertifizierte Prozesse", "correct": true, "because": "Garantieren Standards"}, {"text": "Schnelle Bearbeitung", "correct": false, "because": "Qualität wichtiger"}, {"text": "Minimale Tests", "correct": false, "because": "Risiko für Fehler"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Wiederaufbereitung dasselbe wie Reparatur?', 3, '[{"text": "Nein", "correct": true, "because": "Reparatur behebt nur Fehler"}, {"text": "Ja", "correct": false, "because": "Wiederaufbereitung umfassender"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Wiederaufbereitung von Elektronik?', 5, '[{"text": "Kosteneinsparung", "correct": true, "because": "Günstiger als neu"}, {"text": "Umweltschutz", "correct": true, "because": "Weniger Abfall"}, {"text": "Schnellere Produktion", "correct": false, "because": "Kein Vorteil"}, {"text": "Exklusive Designs", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Wiederaufbereitung eines Monitors unwichtig?', 3, '[{"text": "Bildqualität", "correct": false, "because": "Kern der Funktion"}, {"text": "Anschlüsse", "correct": false, "because": "Entscheidend für Nutzung"}, {"text": "Standfußdesign", "correct": true, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie gehe ich vor, wenn ich ein Gerät wiederaufbereite?', 4, '[{"text": "Prüfen, reinigen, testen", "correct": true, "because": "Umfassender Prozess"}, {"text": "Nur reinigen", "correct": false, "because": "Zu eingeschränkt"}, {"text": "Direkt verkaufen", "correct": false, "because": "Ohne Tests riskant"}]');
